/**
 * Expected wOBA on contact for a batted ball, from exit velocity (mph) and launch angle (deg).
 * Direct cell hit when available; otherwise an expanding-radius neighborhood mean (max r=4).
 * Returns null only if no populated cell exists within the search radius (extreme/garbage inputs).
 */
export function xwobaConFromEvLa(ev: number, la: number): number | null {
  if (!isFinite(ev) || !isFinite(la)) return null;
  const e0 = Math.round(ev), l0 = Math.round(la);
  const direct = XWOBACON[e0 + '|' + l0];
  if (direct != null) return direct;
  for (let r = 1; r <= 4; r++) {
    let sum = 0, n = 0;
    for (let de = -r; de <= r; de++) {
      for (let dl = -r; dl <= r; dl++) {
        if (Math.max(Math.abs(de), Math.abs(dl)) !== r) continue; // ring only
        const v = XWOBACON[(e0 + de) + '|' + (l0 + dl)];
        if (v != null) { sum += v; n++; }
      }
    }
    if (n > 0) return Math.round((sum / n) * 1000) / 1000;
  }
  return null;
}

